print('predicted pixel union',np.logical_and(sim,m).sum()/np.logical_or(sim,m).sum(),'stray pixels',(sim&~m).sum())
out=np.ones((*m.shape,3),np.uint8)*245;out[m]=[0,0,0];out[m&~sim]=[255,0,0];out[sim&~m]=[0,0,255]
